nrcy-pack-card[data-plan]').forEach(function(card){const monthly=Number(card.dataset.monthly),yearly=Number(card.dataset.yearly),saving=monthly*12-yearly;card.querySelectorAll('.inrcy-pack-billing button').forEach(function(button){button.addEventListener('click',function(){const annual=button.dataset.cycle==='yearly';card.querySelectorAll('.inrcy-pack-billing button').forEach(function(choice){choice.setAttribute('aria-pressed',String(choice===button));});card.querySelector('[data-price]').textContent=(annual?yearly:monthly).toLocaleString('fr-FR')+' €';card.querySelector('[data-price-period]').textContent=annual?'HT / an':'HT / mois';card.querySelector('[data-price-note]').textContent=annual?'Facturé annuellement. '+saving.toLocaleString('fr-FR')+' € économisés par rapport à 12 mensualités.':'Facturé mensuellement. Annuel : '+yearly.toLocaleString('fr-FR')+' € HT / an.';});});});const elements=root.querySelectorAll('.inrcy-pack-card,.inrcy-comparison,.inrcy-partner');if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||!('IntersectionObserver'in window)){elements.forEach(e=>e.classList.add('inrcy-visible'));return;}const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('inrcy-visible');observer.unobserve(entry.target);}})},{threshold:.12});elements.forEach(e=>observer.observe(e));})();</script></div>
